// States where this client deliberately does not do what the original did.
// `step` counts the states of the script from 0 (the state after opening).
struct KnownDifference final
{
    bool modern;
    const char *script;
    int step;
    const char *why;
};

inline constexpr KnownDifference known_differences[]{
    // 1.6.3.8's CrateScreen clears _holdingItem on Escape without returning it:
    // the stack on the cursor is destroyed. 1.9.9.8 hands it back; so do we.
    {false, "crate.escape_with_held", 3, "the held stack is returned to the inventory, not destroyed"},
};
